-- Procedimiento nuevo, creado en el esquema corresponsales (mismo esquema que pkf_transaccion, sin necesidad de grants cruzados):
CREATE OR REPLACE PROCEDURE corresponsales.p_obtiene_ced_suc_corresponsal (
    pin_codigo_socio    IN  NUMBER,
    pov_cedula          OUT VARCHAR2,
    pon_codigo_sucursal OUT NUMBER,
    pov_error           OUT VARCHAR2
) IS
BEGIN
    pov_error := NULL;
    SELECT cr_identificacion, codigo_sucursal
    INTO   pov_cedula, pon_codigo_sucursal
    FROM   corresponsales.corresponsalRepresentante
    WHERE  cr_cod_socio = pin_codigo_socio
    AND    ROWNUM = 1;
EXCEPTION
    WHEN NO_DATA_FOUND THEN pov_error := 'No existio datos para el socio con codigo N: ' || pin_codigo_socio;
    WHEN TOO_MANY_ROWS THEN pov_error := 'Se encontro mas de un registro para el socio con codigo N: ' || pin_codigo_socio;
    WHEN OTHERS THEN pov_error := 'Error al obtener datos del corresponsal para el socio con codigo N: ' || pin_codigo_socio || ' - ' || SQLERRM;
END p_obtiene_ced_suc_corresponsal;

